style.css:
@-moz-document domain("wattpad.com") {
/* Đổi phông chữ text thường, giữ nguyên đậm nghiêng và bảo vệ emoji/icon */
    body, div:not([class*="icon"]):not([class*="emoji"]), 
    p:not([class*="icon"]):not([class*="emoji"]), 
    span:not([class*="icon"]):not([class*="emoji"]), 
    h1, h2, h3 {
        font-family: 'Times New Roman', Times, serif !important;
    }

    /* Giữ nguyên chữ in nghiêng chuẩn Times New Roman */
    i, em, [style*="font-style: italic"], [style*="font-style:italic"] {
        font-family: 'Times New Roman', Times, serif !important;
        font-style: italic !important;
    }

    /* Giữ nguyên chữ in đậm chuẩn Times New Roman */
    b, strong, [style*="font-weight: bold"], [style*="font-weight:bold"] {
        font-family: 'Times New Roman', Times, serif !important;
        font-weight: bold !important;
    }
}
